package vn.hust.restaurant.controller;import java.sql.*;import java.util.*;import vn.hust.restaurant.model.*;import vn.hust.restaurant.service.OrderService;public class OrderController{private final OrderService s;public OrderController(OrderService s){this.s=s;}public Optional<OrderSummary>active(int t)throws SQLException{return s.active(t);}public List<OrderSummary>open()throws SQLException{return s.open();}public long create(int t,int e)throws SQLException{return s.create(t,e);}public void add(long o,int m,int q,String n)throws SQLException{s.add(o,m,q,n);}public List<OrderItemView>items(long o)throws SQLException{return s.items(o);}public void remove(long i)throws SQLException{s.remove(i);}public void send(long i)throws SQLException{s.send(i);}public void ready(long i)throws SQLException{s.ready(i);}public void cancel(long i)throws SQLException{s.cancel(i);}}